$(document).ready(function(){$(document).on("click",".delete-value",function(event){event.preventDefault();var $this=$(this),dataurl=$this.data("url"),id=$this.data("id");$Confirm({},function(result){result.value&&$.ajax({url:dataurl,type:"Get",dataType:"json",data:{}}).done(function(data){if(data.success)$notification.success("",window.localization.deleted_successfully,2e3,"fa fa-check"),$this.parents('tr[id="tr-'+id+'"]').remove();else{var errors=data.errors;errors.length>0&&(txt=MakeErrorsMsg(errors),$notification.error("",txt,3500,"fa fa-exclamation-circle"))}}).fail(function(jqXHR,Status){$notification.error(errorTitle,jqXHR.statusText,2e3,"fa fa-exclamation-circle")})})})});